from sqlalchemy import Column,Integer,Numeric,String,ForeignKey,Date,DateTime,Text,CheckConstraint,UniqueConstraint
from sqlalchemy.sql import func
from app.database.base import Base
class MRPPlan(Base):
 __tablename__="mrp_plans"
 id=Column(Integer,primary_key=True); company_id=Column(Integer,ForeignKey("companies.id",ondelete="CASCADE"),nullable=False,index=True)
 warehouse_id=Column(Integer,nullable=True,index=True); plan_date=Column(Date,nullable=False); status=Column(String(20),nullable=False,default="draft"); notes=Column(Text); created_by=Column(Integer,nullable=True); created_at=Column(DateTime(timezone=True),server_default=func.now(),nullable=False)
 __table_args__=(CheckConstraint("status IN ('draft','approved','released','closed','cancelled')",name="ck_mrp_plan_status"),)
class MRPRequirement(Base):
 __tablename__="mrp_requirements"
 id=Column(Integer,primary_key=True); plan_id=Column(Integer,ForeignKey("mrp_plans.id",ondelete="CASCADE"),nullable=False,index=True); item_id=Column(Integer,nullable=False,index=True); variant_id=Column(Integer,nullable=True,index=True); demand_quantity=Column(Numeric(18,4),nullable=False); on_hand_quantity=Column(Numeric(18,4),nullable=False,default=0); reserved_quantity=Column(Numeric(18,4),nullable=False,default=0); supply_quantity=Column(Numeric(18,4),nullable=False,default=0); shortage_quantity=Column(Numeric(18,4),nullable=False,default=0); suggested_quantity=Column(Numeric(18,4),nullable=False,default=0); production_order_id=Column(Integer,ForeignKey("manufacturing_work_orders.id",ondelete="SET NULL"),nullable=True,index=True); source_type=Column(String(30),nullable=False,default="demand"); source_id=Column(Integer,nullable=True)
 __table_args__=(CheckConstraint("demand_quantity >= 0 AND on_hand_quantity >= 0 AND reserved_quantity >= 0 AND supply_quantity >= 0 AND shortage_quantity >= 0 AND suggested_quantity >= 0",name="ck_mrp_req_nonnegative"),)
class MRPWorkCenter(Base):
 __tablename__="mrp_work_centers"
 id=Column(Integer,primary_key=True); company_id=Column(Integer,ForeignKey("companies.id",ondelete="CASCADE"),nullable=False,index=True); code=Column(String(60),nullable=False); name=Column(String(200),nullable=False); capacity_hours_per_day=Column(Numeric(12,4),nullable=False,default=8); efficiency_percent=Column(Numeric(8,4),nullable=False,default=100); hourly_cost=Column(Numeric(18,4),nullable=False,default=0); status=Column(String(20),nullable=False,default="active")
 __table_args__=(UniqueConstraint("company_id","code",name="uq_mrp_work_center_code"),CheckConstraint("capacity_hours_per_day > 0",name="ck_mrp_wc_capacity"),CheckConstraint("efficiency_percent > 0 AND efficiency_percent <= 200",name="ck_mrp_wc_efficiency"),CheckConstraint("hourly_cost >= 0",name="ck_mrp_wc_cost"),CheckConstraint("status IN ('active','inactive','maintenance')",name="ck_mrp_wc_status"),)
class MRPRoutingOperation(Base):
 __tablename__="mrp_routing_operations"
 id=Column(Integer,primary_key=True); company_id=Column(Integer,ForeignKey("companies.id",ondelete="CASCADE"),nullable=False,index=True); item_id=Column(Integer,nullable=False,index=True); variant_id=Column(Integer,nullable=True); sequence=Column(Integer,nullable=False); work_center_id=Column(Integer,ForeignKey("mrp_work_centers.id",ondelete="RESTRICT"),nullable=False); setup_minutes=Column(Numeric(12,4),nullable=False,default=0); run_minutes_per_unit=Column(Numeric(12,4),nullable=False,default=0); queue_minutes=Column(Numeric(12,4),nullable=False,default=0); move_minutes=Column(Numeric(12,4),nullable=False,default=0); scrap_percent=Column(Numeric(8,4),nullable=False,default=0); description=Column(Text)
 __table_args__=(UniqueConstraint("company_id","item_id","variant_id","sequence",name="uq_mrp_routing_seq"),CheckConstraint("sequence > 0",name="ck_mrp_route_seq"),CheckConstraint("setup_minutes >= 0 AND run_minutes_per_unit >= 0 AND queue_minutes >= 0 AND move_minutes >= 0",name="ck_mrp_route_times"),CheckConstraint("scrap_percent >= 0 AND scrap_percent < 100",name="ck_mrp_route_scrap"),)
class MRPScheduleSlot(Base):
 __tablename__="mrp_schedule_slots"
 id=Column(Integer,primary_key=True); company_id=Column(Integer,ForeignKey("companies.id",ondelete="CASCADE"),nullable=False,index=True); work_center_id=Column(Integer,ForeignKey("mrp_work_centers.id",ondelete="RESTRICT"),nullable=False); item_id=Column(Integer,nullable=False); variant_id=Column(Integer,nullable=True); source_id=Column(Integer,nullable=True); start_at=Column(DateTime(timezone=True),nullable=False); end_at=Column(DateTime(timezone=True),nullable=False); planned_quantity=Column(Numeric(18,4),nullable=False); status=Column(String(20),nullable=False,default="planned")
 __table_args__=(CheckConstraint("end_at > start_at",name="ck_mrp_slot_time"),CheckConstraint("planned_quantity > 0",name="ck_mrp_slot_qty"),CheckConstraint("status IN ('planned','released','in_progress','completed','cancelled')",name="ck_mrp_slot_status"),)
class MRPProductionCost(Base):
 __tablename__="mrp_production_costs"
 id=Column(Integer,primary_key=True); company_id=Column(Integer,ForeignKey("companies.id",ondelete="CASCADE"),nullable=False,index=True); source_id=Column(Integer,nullable=False); planned_material=Column(Numeric(18,4),nullable=False,default=0); actual_material=Column(Numeric(18,4),nullable=False,default=0); planned_labor=Column(Numeric(18,4),nullable=False,default=0); actual_labor=Column(Numeric(18,4),nullable=False,default=0); planned_overhead=Column(Numeric(18,4),nullable=False,default=0); actual_overhead=Column(Numeric(18,4),nullable=False,default=0); status=Column(String(20),nullable=False,default="open"); variance_material=Column(Numeric(18,4),nullable=False,default=0); variance_labor=Column(Numeric(18,4),nullable=False,default=0); variance_overhead=Column(Numeric(18,4),nullable=False,default=0)
